"use client"

import type * as React from "react"

import { cn } from "@/lib/utils"

import { getFileThumbnailExtension } from "./file-thumbnail-extension"
import { FileThumbnailFallback } from "./file-thumbnail-fallback"
import type {
  FileThumbnailFrameProps,
  FileThumbnailState,
} from "./file-thumbnail-frame-types"
import { FileThumbnailImage } from "./file-thumbnail-image"
import { FileThumbnailShimmer } from "./file-thumbnail-shimmer"

export { FileThumbnailShimmer }
export type { FileThumbnailFrameProps, FileThumbnailState }

/**
 * The dependency-free thumbnail frame: loading shimmer, image fade-in,
 * custom-rendered preview slot, and extension fallback.
 */
export function FileThumbnailFrame({
  file,
  className,
  previewAspectRatio,
  previewClassName,
  previewContent,
  previewImageUrl,
  onPreviewError,
  state,
  style,
  ...props
}: FileThumbnailFrameProps) {
  const extension = getFileThumbnailExtension(file)
  const hasRenderableContent = hasRenderablePreviewContent(previewContent)
  const resolvedState = resolveFileThumbnailState({
    explicitState: state,
    hasPreview: hasRenderableContent || Boolean(previewImageUrl),
  })

  return (
    <div
      {...props}
      data-slot="file-thumbnail"
      className={cn(
        "relative overflow-hidden rounded-md border bg-muted text-muted-foreground",
        className
      )}
      style={{
        ...style,
        aspectRatio: style?.aspectRatio ?? String(previewAspectRatio ?? 3 / 4),
      }}
    >
      {resolvedState === "loading" ? (
        <FileThumbnailShimmer />
      ) : resolvedState === "error" ? (
        <FileThumbnailFallback extension={extension} />
      ) : hasRenderableContent ? (
        <div className={cn("absolute inset-0", previewClassName)}>
          {previewContent}
        </div>
      ) : previewImageUrl ? (
        <FileThumbnailImage
          key={previewImageUrl}
          url={previewImageUrl}
          alt={file.name}
          className={previewClassName}
          fallback={<FileThumbnailFallback extension={extension} />}
          onError={onPreviewError}
        />
      ) : (
        <FileThumbnailFallback extension={extension} />
      )}
    </div>
  )
}

export function resolveFileThumbnailState({
  explicitState,
  hasPreview,
}: {
  explicitState?: FileThumbnailState
  hasPreview: boolean
}): FileThumbnailState {
  if (explicitState) return explicitState
  return hasPreview ? "loaded" : "error"
}

export function hasRenderablePreviewContent(value: React.ReactNode): boolean {
  return value !== null && value !== undefined && value !== false
}

import type * as React from "react"

export interface ThumbnailFile {
  name: string
  type: string
}

export type FileThumbnailState = "loading" | "loaded" | "error"

export interface FileThumbnailFrameProps
  extends Omit<React.ComponentPropsWithoutRef<"div">, "children"> {
  /** The file being previewed. A browser `File` works too. */
  file: ThumbnailFile | File
  /** Aspect ratio of the preview frame (width / height). Defaults to 3 / 4. */
  previewAspectRatio?: number
  previewClassName?: string
  /** Custom React preview (e.g. a rendered PDF page). Takes priority over the image. */
  previewContent?: React.ReactNode
  /** Externally generated thumbnail image URL. */
  previewImageUrl?: string | null
  /** Called when the browser image preview fails to load. */
  onPreviewError?: () => void
  /** Explicit preview lifecycle. */
  state?: FileThumbnailState
}

import type { ThumbnailFile } from "./file-thumbnail-frame-types"

export function getFileThumbnailExtension(
  file: ThumbnailFile | File
): string | null {
  const fromName = extensionFromName(file.name)
  if (fromName) return fromName.toLowerCase()
  const subtype = mimeSubtypeToExtension(file.type)
  return subtype ? subtype.toLowerCase() : null
}

function extensionFromName(name: string | undefined): string | null {
  if (!name) return null
  const clean = name.split(/[?#]/)[0]
  const base = clean.split(/[\\/]/).pop() ?? clean
  if (!base.includes(".")) return null
  return base.split(".").pop() || null
}

function mimeSubtypeToExtension(type: string | undefined): string | null {
  if (!type) return null
  const normalized = type.toLowerCase().split(";")[0].trim()
  if (normalized in MIME_EXTENSION) return MIME_EXTENSION[normalized]
  const subtype = normalized.split("/").pop()
  return subtype || null
}

const MIME_EXTENSION: Record<string, string> = {
  "application/pdf": "pdf",
  "application/vnd.ms-excel": "xls",
  "application/vnd.ms-powerpoint": "ppt",
  "application/vnd.openxmlformats-officedocument.presentationml.presentation":
    "pptx",
  "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet": "xlsx",
  "application/vnd.openxmlformats-officedocument.wordprocessingml.document":
    "docx",
  "image/jpeg": "jpg",
  "image/png": "png",
  "image/tiff": "tiff",
  "text/csv": "csv",
  "text/html": "html",
  "text/markdown": "md",
  "text/plain": "txt",
}

export function FileThumbnailFallback({
  extension,
}: {
  extension: string | null
}) {
  return (
    <div
      data-slot="file-thumbnail-fallback"
      className="absolute inset-0 flex flex-col items-center justify-center gap-1.5"
    >
      <svg
        viewBox="0 0 24 24"
        className="size-1/3 opacity-40"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        aria-hidden
      >
        <path d="M6 2.5h8L19 7v13.5a1 1 0 0 1-1 1H6a1 1 0 0 1-1-1v-17a1 1 0 0 1 1-1Z" />
        <path d="M14 2.5V7h5" />
      </svg>
      {extension ? (
        <span className="max-w-[80%] truncate text-[0.625rem] font-medium tracking-wide uppercase opacity-70">
          {extension}
        </span>
      ) : null}
    </div>
  )
}

"use client"

import * as React from "react"

export function FileThumbnailShimmer() {
  const highlightRef = React.useRef<HTMLDivElement | null>(null)
  const prefersReducedMotion = usePrefersReducedMotion()

  React.useEffect(() => {
    const highlight = highlightRef.current
    if (!highlight || prefersReducedMotion || !highlight.animate) return

    const animation = highlight.animate(
      [{ backgroundPosition: "200% 0" }, { backgroundPosition: "-200% 0" }],
      {
        duration: 1600,
        iterations: Infinity,
        easing: "linear",
      }
    )

    return () => animation.cancel()
  }, [prefersReducedMotion])

  return (
    <div
      aria-hidden
      data-slot="file-thumbnail-shimmer"
      className="absolute inset-0 overflow-hidden bg-muted"
    >
      <div
        ref={highlightRef}
        data-slot="file-thumbnail-shimmer-highlight"
        className="absolute inset-0"
        style={{
          backgroundImage:
            "linear-gradient(120deg, transparent 35%, var(--skeleton-highlight, color-mix(in oklab, var(--background) 85%, transparent)) 50%, transparent 65%)",
          backgroundSize: "200% 100%",
          backgroundRepeat: "no-repeat",
          backgroundPosition: prefersReducedMotion ? "50% 0" : "200% 0",
        }}
      />
    </div>
  )
}

function usePrefersReducedMotion(): boolean {
  return React.useSyncExternalStore(
    subscribeToReducedMotion,
    getReducedMotionSnapshot,
    () => false
  )
}

function subscribeToReducedMotion(onChange: () => void) {
  if (typeof window === "undefined" || !window.matchMedia) return () => {}

  const query = window.matchMedia("(prefers-reduced-motion: reduce)")
  if (query.addEventListener) {
    query.addEventListener("change", onChange)
    return () => query.removeEventListener("change", onChange)
  }

  const legacyQuery = query as MediaQueryList & {
    addListener?: (listener: () => void) => void
    removeListener?: (listener: () => void) => void
  }
  legacyQuery.addListener?.(onChange)
  return () => legacyQuery.removeListener?.(onChange)
}

function getReducedMotionSnapshot() {
  if (typeof window === "undefined" || !window.matchMedia) return false

  return window.matchMedia("(prefers-reduced-motion: reduce)").matches
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

import { FileThumbnailShimmer } from "./file-thumbnail-shimmer"

export function FileThumbnailImage({
  url,
  alt,
  className,
  fallback,
  onError,
}: {
  url: string
  alt: string
  className?: string
  fallback: React.ReactNode
  onError?: () => void
}) {
  const [loaded, setLoaded] = React.useState(false)
  const [failed, setFailed] = React.useState(false)
  const didReportErrorRef = React.useRef(false)

  const reportError = React.useCallback(() => {
    if (didReportErrorRef.current) return
    didReportErrorRef.current = true
    onError?.()
  }, [onError])

  // A cached image can complete before React attaches `onLoad`.
  const imgRef = React.useCallback(
    (img: HTMLImageElement | null) => {
      if (!img) return
      if (img.complete) {
        if (img.naturalWidth > 0) setLoaded(true)
        else {
          setFailed(true)
          reportError()
        }
      }
    },
    [reportError]
  )

  if (failed) return <>{fallback}</>

  return (
    <>
      <img
        ref={imgRef}
        src={url}
        alt={alt}
        loading="lazy"
        decoding="async"
        onLoad={() => setLoaded(true)}
        onError={() => {
          setFailed(true)
          reportError()
        }}
        className={cn(
          "absolute inset-0 size-full object-cover transition-opacity duration-300",
          loaded ? "opacity-100" : "opacity-0",
          className
        )}
      />
      {loaded ? null : <FileThumbnailShimmer />}
    </>
  )
}
